import itertools

def solve_small(N):
    # Generators are (i, i+1) for i=0..N-2 and (N-1, 0)
    generators = []
    for i in range(N - 1):
        generators.append(tuple(sorted((i, i+1))))
    generators.append(tuple(sorted((0, N-1))))

    perms = list(itertools.permutations(range(N)))

    # Identify orbits under rotation
    def rotate(p):
        return tuple(p[1:] + p[:1])

    orbits = []
    seen = set()
    for p in perms:
        if p not in seen:
            orbit = []
            curr = p
            while curr not in seen:
                seen.add(curr)
                orbit.append(curr)
                curr = rotate(curr)
            orbits.append(orbit)

    # Distance between orbits
    # Distance between permutations p1 and p2 with generators
    def dist(p1, p2):
        # BFS
        q = [(p1, 0)]
        visited = {p1}
        for curr_p, d in q:
            if curr_p == p2:
                return d
            for gen in generators:
                # swap elements at indices gen[0] and gen[1]
                p_list = list(curr_p)
                p_list[gen[0]], p_list[gen[1]] = p_list[gen[1]], p_list[gen[0]]
                next_p = tuple(p_list)
                if next_p not in visited:
                    visited.add(next_p)
                    q.append((next_p, d + 1))
        return -1

    # Distance between orbits O1 and O2 is min dist(p1, p2) for p1 in O1, p2 in O2
    # Actually, since it's distance in a graph, we can just take one p1 from O1
    # and find min distance to any p2 in O2.
    max_d = 0
    for i in range(len(orbits)):
        for j in range(i + 1, len(orbits)):
            min_d = float('inf')
            p1 = orbits[i][0]
            for p2 in orbits[j]:
                min_d = min(min_d, dist(p1, p2))
            max_d = max(max_d, min_d)
    return max_d

for N in range(3, 8):
    print(f"N={N}, max_dist={solve_small(N)}")

