def solve_small_fast(N):
    # Generators are (i, i+1) for i=0..N-2 and (N-1, 0)
    generators = []
    for i in range(N - 1):
        generators.append((i, i+1))
    generators.append((N-1, 0))

    perms = list(itertools.permutations(range(N)))

    # Identify orbits under rotation
    def rotate(p):
        return tuple(p[1:] + p[:1])

    orbits = []
    seen = set()
    for p in perms:
        if p not in seen:
            orbit = []
            curr = p
            while curr not in seen:
                seen.add(curr)
                orbit.append(curr)
                curr = rotate(curr)
            orbits.append(orbit)

    # The distance between orbits O1 and O2 is the shortest path in a graph 
    # where nodes are orbits and an edge exists between O1 and O2 if there's 
    # a permutation p1 in O1 and a generator g such that g(p1) is in O2.

    # Let's build the graph of orbits.
    adj = [[] for _ in range(len(orbits))]
    # First, find which orbit each permutation belongs to.
    perm_to_orbit = {}
    for idx, orbit in enumerate(orbits):
        for p in orbit:
            perm_to_orbit[p] = idx

    for idx, orbit in enumerate(orbits):
        for p in orbit:
            for g in generators:
                p_list = list(p)
                p_list[g[0]], p_list[g[1]] = p_list[g[1]], p_list[g[0]]
                next_p = tuple(p_list)
                next_orbit = perm_to_orbit[next_p]
                if next_orbit != idx:
                    adj[idx].append(next_orbit)

    # Now find the diameter of this graph.
    max_d = 0
    for i in range(len(orbits)):
        q = deque([(i, 0)])
        visited = {i}
        while q:
            u, d = q.popleft()
            max_d = max(max_d, d)
            for v in adj[u]:
                if v not in visited:
                    visited.add(v)
                    q.append((v, d + 1))
    return max_d

