def solve_small_fast_v4(N):
    generators = []
    for i in range(N - 1):
        generators.append((i, i+1))
    generators.append((N-1, 0))

    perms = list(itertools.permutations(range(N)))

    def rotate(p):
        return tuple(p[1:] + p[:1])

    orbit_reps = []
    seen = set()
    for p in perms:
        if p not in seen:
            orbit_reps.append(p)
            curr = p
            while curr not in seen:
                seen.add(curr)
                curr = rotate(curr)

    # Now we have orbit_reps. Let's find the distances between them.
    # But we need the distance between orbits.
    # The distance between orbit O_p and orbit O_q is the shortest distance 
    # between any p' in O_p and any q' in O_q.
    # This is the same as min_k d(p, rotate^k(q)).

    # To compute d(p, q) for all p, q in a small enough space:
    # For a fixed p, BFS to find d(p, q) for all q.

    # But we need to do this for all p in orbit_reps.
    # Let's use the graph of orbits again.

    perm_to_orbit = {}
    # We need to know which orbit each permutation belongs to.
    # Let's redo the orbit finding.
    all_perms_to_orbit = {}
    orbits = []
    seen_perms = set()
    for p in perms:
        if p not in seen_perms:
            orbit = []
            curr = p
            while curr not in seen_perms:
                seen_perms.add(curr)
                orbit.append(curr)
                curr = rotate(curr)
            orbits.append(orbit)
            for o_p in orbit:
                all_perms_to_orbit[o_p] = len(orbits) - 1

    adj = [set() for _ in range(len(orbits))]
    for i, orbit in enumerate(orbits):
        for p in orbit:
            for g in generators:
                p_list = list(p)
                p_list[g[0]], p_list[g[1]] = p_list[g[1]], p_list[g[0]]
                next_p = tuple(p_list)
                next_orbit = all_perms_to_orbit[next_p]
                if next_orbit != i:
                    adj[i].add(next_orbit)

    max_d = 0
    for i in range(len(orbits)):
        q = deque([(i, 0)])
        visited = {i}
        while q:
            u, d = q.popleft()
            max_d = max(max_d, d)
            for v in adj[u]:
                if v not in visited:
                    visited.add(v)
                    q.append((v, d + 1))
    return max_d

