import itertools

def count_inversions(p):
    inv = 0
    for i in range(len(p)):
        for j in range(i + 1, len(p)):
            if p[i] > p[j]:
                inv += 1
    return inv

def solve_max_min_L(N):
    max_min_L = 0
    for p in itertools.permutations(range(N)):
        # Find min L over all rotations
        min_L = float('inf')
        curr_p = p
        for _ in range(N):
            min_L = min(min_L, count_inversions(curr_p))
            curr_p = curr_p[1:] + curr_p[:1]
        max_min_L = max(max_min_L, min_L)
    return max_min_L

for N in range(3, 9):
    print(f"N={N}, max_min_L={solve_max_min_L(N)}")

from collections import deque

def circular_dist(N, target):
    generators = []
    for i in range(N - 1):
        generators.append((i, i+1))
    generators.append((N-1, 0))

    q = deque([(tuple(range(N)), 0)])
    visited = {tuple(range(N))}
    while q:
        curr, d = q.popleft()
        if curr == target:
            return d
        for g in generators:
            p_list = list(curr)
            p_list[g[0]], p_list[g[1]] = p_list[g[1]], p_list[g[0]]
            next_p = tuple(p_list)
            if next_p not in visited:
                visited.add(next_p)
                q.append((next_p, d + 1))
    return -1

